{"command":"create","path":"/workspace/source/packages/privacy/src/erasure-guard.ts","file_text":"import { pool } from '../../database/src/pool.js';

/** Returns true when the merchant has completed (or is tracking) erasure for this customer. */
export async function isCustomerErased(merchantId: string, customerId: string): Promise<boolean> {
  const result = await pool.query(
    `SELECT 1 FROM customers.erased_customers WHERE merchant_id=$1 AND customer_id=$2`,
    [merchantId, customerId],
  );
  return Boolean(result.rowCount);
}

export async function assertCustomerNotErased(merchantId: string, customerId: string): Promise<void> {
  if (await isCustomerErased(merchantId, customerId)) {
    throw Object.assign(new Error('customer has been erased'), { statusCode: 409, code: 'customer_erased' });
  }
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-repository.ts","file_text":"import type pg from 'pg';
import { pool } from '../../../packages/database/src/pool.js';

export type ErasureStatus = 'pending' | 'processing' | 'failed' | 'completed';

export interface ErasureRequestRow {
  id: string;
  merchant_id: string;
  customer_id: string;
  status: ErasureStatus;
  attempts: number;
  created_at: Date;
  updated_at: Date;
  completed_at: Date | null;
  last_error: string | null;
}

export interface ErasureRequestResponse {
  id: string;
  customerId: string;
  status: ErasureStatus;
  attempts: number;
  createdAt: string;
  updatedAt: string;
  completedAt: string | null;
  lastError: string | null;
}

export function toErasureResponse(row: ErasureRequestRow): ErasureRequestResponse {
  return {
    id: row.id,
    customerId: row.customer_id,
    status: row.status,
    attempts: row.attempts,
    createdAt: row.created_at.toISOString(),
    updatedAt: row.updated_at.toISOString(),
    completedAt: row.completed_at ? row.completed_at.toISOString() : null,
    lastError: row.last_error,
  };
}

export class ErasureRepository {
  async findCustomer(merchantId: string, customerId: string): Promise<boolean> {
    const result = await pool.query(
      `SELECT 1 FROM customers.customers WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    if (result.rowCount) return true;
    const erased = await pool.query(
      `SELECT 1 FROM customers.erased_customers WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return Boolean(erased.rowCount);
  }

  async findRequest(merchantId: string, requestId: string): Promise<ErasureRequestRow | undefined> {
    const result = await pool.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,created_at,updated_at,completed_at,last_error
       FROM customers.erasure_requests WHERE merchant_id=$1 AND id=$2`,
      [merchantId, requestId],
    );
    return result.rows[0];
  }

  async findOpenOrCompletedForCustomer(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `SELECT id,merchant_id,customer_id,status,attempts,created_at,updated_at,completed_at,last_error
       FROM customers.erasure_requests
       WHERE merchant_id=$1 AND customer_id=$2
       FOR UPDATE`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async findByIdempotencyKey(
    client: pg.PoolClient,
    merchantId: string,
    idempotencyKey: string,
  ): Promise<{ customer_id: string; request_id: string } | undefined> {
    const result = await client.query<{ customer_id: string; request_id: string }>(
      `SELECT customer_id,request_id FROM customers.erasure_request_keys
       WHERE merchant_id=$1 AND idempotency_key=$2 FOR UPDATE`,
      [merchantId, idempotencyKey],
    );
    return result.rows[0];
  }

  async createRequest(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<ErasureRequestRow> {
    const result = await client.query<ErasureRequestRow>(
      `INSERT INTO customers.erasure_requests(id,merchant_id,customer_id,status,attempts)
       VALUES($1,$2,$3,'pending',0)
       RETURNING id,merchant_id,customer_id,status,attempts,created_at,updated_at,completed_at,last_error`,
      [requestId, merchantId, customerId],
    );
    return result.rows[0]!;
  }

  async saveIdempotencyKey(
    client: pg.PoolClient,
    merchantId: string,
    idempotencyKey: string,
    customerId: string,
    requestId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO customers.erasure_request_keys(merchant_id,idempotency_key,customer_id,request_id)
       VALUES($1,$2,$3,$4)`,
      [merchantId, idempotencyKey, customerId, requestId],
    );
  }

  async requeueFailed(
    client: pg.PoolClient,
    requestId: string,
  ): Promise<ErasureRequestRow | undefined> {
    const result = await client.query<ErasureRequestRow>(
      `UPDATE customers.erasure_requests
       SET status='pending', available_at=now(), updated_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE id=$1 AND status='failed'
       RETURNING id,merchant_id,customer_id,status,attempts,created_at,updated_at,completed_at,last_error`,
      [requestId],
    );
    return result.rows[0];
  }

  async audit(
    client: pg.PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
    correlationId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO platform.audit_logs(merchant_id,actor_type,target_type,target_id,action,metadata,correlation_id)
       VALUES($1,'api_key','customer',$2,'customer.erasure.requested',$3,$4)`,
      [merchantId, customerId, { requestId }, correlationId],
    );
  }
}
"}

{"command":"create","path":"/workspace/source/apps/customer-service/src/erasure-service.ts","file_text":"import { v4 as uuid } from 'uuid';
import { transaction } from '../../../packages/database/src/pool.js';
import {
  ErasureRepository,
  toErasureResponse,
  type ErasureRequestResponse,
} from './erasure-repository.js';

export class ErasureService {
  constructor(private readonly repository = new ErasureRepository()) {}

  async create(
    merchantId: string,
    customerId: string,
    idempotencyKey: string,
  ): Promise<{ status: number; body: ErasureRequestResponse }> {
    if (idempotencyKey.length < 8 || idempotencyKey.length > 200) {
      throw Object.assign(new Error('valid_idempotency_key_required'), { statusCode: 400 });
    }

    const exists = await this.repository.findCustomer(merchantId, customerId);
    if (!exists) throw Object.assign(new Error('customer_not_found'), { statusCode: 404 });

    return transaction(async (client) => {
      const byKey = await this.repository.findByIdempotencyKey(client, merchantId, idempotencyKey);
      if (byKey) {
        if (byKey.customer_id !== customerId) {
          throw Object.assign(new Error('idempotency key reused with different customer'), { statusCode: 409 });
        }
        const existing = await this.repository.findRequest(merchantId, byKey.request_id);
        if (!existing) throw Object.assign(new Error('erasure_request_not_found'), { statusCode: 404 });
        if (existing.status === 'failed') {
          const requeued = await this.repository.requeueFailed(client, existing.id);
          if (requeued) return { status: 202, body: toErasureResponse(requeued) };
        }
        return { status: 202, body: toErasureResponse(existing) };
      }

      const existingForCustomer = await this.repository.findOpenOrCompletedForCustomer(
        client, merchantId, customerId,
      );
      if (existingForCustomer) {
        await this.repository.saveIdempotencyKey(
          client, merchantId, idempotencyKey, customerId, existingForCustomer.id,
        );
        if (existingForCustomer.status === 'failed') {
          const requeued = await this.repository.requeueFailed(client, existingForCustomer.id);
          if (requeued) return { status: 202, body: toErasureResponse(requeued) };
        }
        return { status: 202, body: toErasureResponse(existingForCustomer) };
      }

      const requestId = uuid();
      const created = await this.repository.createRequest(client, merchantId, customerId, requestId);
      await this.repository.saveIdempotencyKey(client, merchantId, idempotencyKey, customerId, requestId);
      await this.repository.audit(client, merchantId, customerId, requestId, uuid());
      return { status: 202, body: toErasureResponse(created) };
    });
  }

  async get(merchantId: string, requestId: string): Promise<ErasureRequestResponse | undefined> {
    const row = await this.repository.findRequest(merchantId, requestId);
    return row ? toErasureResponse(row) : undefined;
  }
}
"}

