{"command":"create","path":"/workspace/source/apps/erasure-worker/src/repository.ts","file_text":"import type { PoolClient } from 'pg';
import { pool, transaction } from '../../../packages/database/src/pool.js';
import { boundedExponentialBackoffSeconds } from '../../../packages/operations/src/retry-policy.js';
import { REDACTED, redactedCustomerSnapshot } from '../../../packages/privacy/src/redaction.js';

export interface ClaimedErasureRequest {
  id: string;
  merchant_id: string;
  customer_id: string;
  attempts: number;
  max_attempts: number;
}

export interface CustomerPiiSnapshot {
  email: string;
  name: string;
  phone: string | null;
  external_reference: string;
}

const STABLE_ERROR = 'erasure_step_failed';

export class ErasureWorkerRepository {
  async recoverExpiredLeases(): Promise<number> {
    const result = await pool.query(
      `UPDATE customers.erasure_requests
       SET status='failed', available_at=now(), locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
           last_error=COALESCE(last_error, 'worker_lease_expired'), updated_at=now()
       WHERE status='processing' AND lease_expires_at < now()`,
    );
    return result.rowCount ?? 0;
  }

  async claim(workerId: string, leaseSeconds = 120): Promise<ClaimedErasureRequest | undefined> {
    return await transaction(async (client) => {
      const result = await client.query<ClaimedErasureRequest>(
        `UPDATE customers.erasure_requests
         SET status='processing', attempts=attempts+1, locked_by=$1, locked_at=now(),
             lease_expires_at=now()+($2 || ' seconds')::interval, last_error=NULL, updated_at=now()
         WHERE id=(SELECT id FROM customers.erasure_requests
           WHERE status IN ('pending','failed') AND available_at<=now() AND attempts<max_attempts
           ORDER BY available_at,created_at FOR UPDATE SKIP LOCKED LIMIT 1)
         RETURNING id,merchant_id,customer_id,attempts,max_attempts`,
        [workerId, leaseSeconds],
      );
      return result.rows[0];
    });
  }

  async completedSteps(requestId: string): Promise<Set<string>> {
    const result = await pool.query<{ step: string }>(
      `SELECT step FROM customers.erasure_steps WHERE request_id=$1`,
      [requestId],
    );
    return new Set(result.rows.map((row) => row.step));
  }

  async markStep(client: PoolClient, requestId: string, step: string): Promise<void> {
    await client.query(
      `INSERT INTO customers.erasure_steps(request_id,step) VALUES($1,$2) ON CONFLICT DO NOTHING`,
      [requestId, step],
    );
  }

  async loadCustomerPii(
    merchantId: string,
    customerId: string,
  ): Promise<CustomerPiiSnapshot | undefined> {
    const result = await pool.query<CustomerPiiSnapshot>(
      `SELECT email,name,phone,external_reference FROM customers.customers
       WHERE merchant_id=$1 AND id=$2`,
      [merchantId, customerId],
    );
    return result.rows[0];
  }

  async captureEmailTargets(
    client: PoolClient,
    requestId: string,
    merchantId: string,
    customerId: string,
    snapshot?: CustomerPiiSnapshot,
  ): Promise<string[]> {
    const destinations = new Set<string>();
    if (snapshot?.email) destinations.add(snapshot.email);

    const contacts = await client.query<{ value: string }>(
      `SELECT value FROM customers.contacts
       WHERE merchant_id=$1 AND customer_id=$2 AND kind='email'`,
      [merchantId, customerId],
    );
    for (const row of contacts.rows) destinations.add(row.value);

    const prefs = await client.query<{ destination: string }>(
      `SELECT destination FROM operations.notification_preferences
       WHERE merchant_id=$1 AND customer_id=$2 AND channel='email'`,
      [merchantId, customerId],
    );
    for (const row of prefs.rows) destinations.add(row.destination);

    const deliveries = await client.query<{ destination: string }>(
      `SELECT DISTINCT destination FROM operations.email_deliveries
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of deliveries.rows) destinations.add(row.destination);

    const notifications = await client.query<{ destination: string }>(
      `SELECT DISTINCT destination FROM operations.notifications
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    for (const row of notifications.rows) destinations.add(row.destination);

    const refunds = await client.query<{ customer_email: string }>(
      `SELECT DISTINCT customer_email FROM payments.refunds r
       JOIN payments.payment_intents p ON p.id=r.payment_intent_id
       WHERE p.merchant_id=$1 AND p.customer_id=$2 AND r.customer_email IS NOT NULL`,
      [merchantId, customerId],
    );
    for (const row of refunds.rows) destinations.add(row.customer_email);

    const analytics = await client.query<{ email: string }>(
      `SELECT DISTINCT email FROM operations.analytics_events
       WHERE merchant_id=$1 AND customer_id=$2 AND email IS NOT NULL`,
      [merchantId, customerId],
    );
    for (const row of analytics.rows) destinations.add(row.email);

    const list = [...destinations].filter((value) => value && value !== REDACTED.email);
    for (const destination of list) {
      await client.query(
        `INSERT INTO customers.erasure_email_targets(request_id,destination)
         VALUES($1,$2) ON CONFLICT DO NOTHING`,
        [requestId, destination],
      );
    }
    return list;
  }

  async loadEmailTargets(requestId: string): Promise<string[]> {
    const result = await pool.query<{ destination: string }>(
      `SELECT destination FROM customers.erasure_email_targets WHERE request_id=$1`,
      [requestId],
    );
    return result.rows.map((row) => row.destination);
  }

  async listDocumentKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    return result.rows.map((row) => row.object_key);
  }

  async listImportKeys(merchantId: string, customerId: string): Promise<string[]> {
    const result = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM customers.customer_imports
       WHERE merchant_id=$1 AND object_key LIKE $2`,
      [merchantId, `%${customerId}%`],
    );
    // Also pull imports whose stored content referenced the customer via manifests metadata.
    const manifests = await pool.query<{ object_key: string }>(
      `SELECT object_key FROM operations.document_manifests
       WHERE merchant_id=$1 AND document_type='customer_import'
         AND (metadata->>'customerId'=$2 OR object_key LIKE $3)`,
      [merchantId, customerId, `%${customerId}%`],
    );
    return [...new Set([...result.rows, ...manifests.rows].map((row) => row.object_key))];
  }

  async tombstoneCustomer(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    const uniqueSuffix = customerId.replaceAll('-', '').slice(0, 12);
    await client.query(
      `UPDATE customers.customers
       SET email=$3, name=$4, phone=NULL, external_reference=$5, metadata='{}'::jsonb,
           status='erased', version=version+1, updated_at=now()
       WHERE merchant_id=$1 AND id=$2`,
      [
        merchantId,
        customerId,
        `erased+${uniqueSuffix}@customer.invalid`,
        REDACTED.name,
        `erased-${uniqueSuffix}`,
      ],
    );
  }

  async redactProfileGraph(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE customers.addresses
       SET line1=$3, line2=NULL, city=$4, region=NULL, postal_code=$5, country=$6
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.line1, REDACTED.city, REDACTED.postalCode, REDACTED.country],
    );
    await client.query(
      `UPDATE customers.contacts SET value=$3 WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.contactValue],
    );
    await client.query(
      `UPDATE customers.payment_method_refs
       SET provider_token='erased', billing_name=$3, billing_address='{}'::jsonb, status='erased'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.billingName],
    );
    await client.query(
      `DELETE FROM customers.provider_customer_mappings WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );

    const tickets = await client.query<{ ticket_id: string }>(
      `SELECT ticket_id FROM customers.support_participants WHERE customer_id=$1`,
      [customerId],
    );
    for (const ticket of tickets.rows) {
      await client.query(
        `UPDATE customers.support_tickets SET subject=$2 WHERE id=$1 AND merchant_id=$3`,
        [ticket.ticket_id, REDACTED.subject, merchantId],
      );
      await client.query(
        `UPDATE customers.support_messages SET body=$2, attachments='[]'::jsonb
         WHERE ticket_id=$1 AND merchant_id=$3`,
        [ticket.ticket_id, REDACTED.body, merchantId],
      );
    }
  }

  async redactFinancialRecords(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    const snapshot = redactedCustomerSnapshot(customerId);
    await client.query(
      `UPDATE payments.payment_intents
       SET customer_snapshot=$3, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, snapshot],
    );
    await client.query(
      `UPDATE payments.refunds r
       SET customer_email=$3
       FROM payments.payment_intents p
       WHERE r.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId, REDACTED.email],
    );
    await client.query(
      `UPDATE payments.disputes d
       SET evidence = COALESCE(d.evidence, '{}'::jsonb) - 'customerEmail' - 'email' - 'customerName' - 'name'
       FROM payments.payment_intents p
       WHERE d.payment_intent_id=p.id AND p.merchant_id=$1 AND p.customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE payments.invoices
       SET billing_snapshot=$3
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, snapshot],
    );
  }

  async redactOperationalRecords(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE operations.notification_preferences
       SET destination=$3, enabled=false, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.destination],
    );
    await client.query(
      `UPDATE operations.notifications
       SET destination=$3, payload='{}'::jsonb, updated_at=now()
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.destination],
    );
    await client.query(
      `UPDATE operations.email_deliveries
       SET destination=$3, subject=$4, text_body=$4, html_body=$4,
           status=CASE WHEN status IN ('pending','failed','processing') THEN 'cancelled' ELSE status END,
           cancelled_at=CASE WHEN status IN ('pending','failed','processing') THEN now() ELSE cancelled_at END,
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.destination, REDACTED.body],
    );
    await client.query(
      `UPDATE operations.analytics_events
       SET email=NULL, anonymous_id=$3, properties='{}'::jsonb
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId, REDACTED.anonymousId],
    );
    await client.query(
      `UPDATE operations.document_manifests
       SET metadata = COALESCE(metadata, '{}'::jsonb) - 'email' - 'name' - 'customerEmail' - 'customerName'
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE platform.audit_logs
       SET metadata='{}'::jsonb
       WHERE merchant_id=$1 AND target_type='customer' AND target_id=$2`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.outbox_events
       SET payload = jsonb_strip_nulls(
         jsonb_set(
           jsonb_set(
             jsonb_set(COALESCE(payload, '{}'::jsonb), '{email}', 'null'::jsonb, true),
             '{customerEmail}', 'null'::jsonb, true
           ),
           '{name}', 'null'::jsonb, true
         )
       )
       WHERE merchant_id=$1 AND (
         aggregate_id=$2 OR payload->>'customerId'=$2::text
       )`,
      [merchantId, customerId],
    );
    await client.query(
      `UPDATE operations.jobs
       SET payload = jsonb_set(
         COALESCE(payload, '{}'::jsonb),
         '{customerSnapshot}',
         $3::jsonb,
         true
       )
       WHERE merchant_id=$1 AND payload->>'customerId'=$2::text`,
      [merchantId, customerId, JSON.stringify(redactedCustomerSnapshot(customerId))],
    );
    await client.query(
      `UPDATE operations.dead_letters
       SET payload = COALESCE(payload, '{}'::jsonb) - 'email' - 'customerEmail' - 'name' - 'destination'
       WHERE (payload->>'customerId'=$1::text OR payload->>'merchantId'=$2::text)
         AND (payload->>'customerId'=$1::text)`,
      [customerId, merchantId],
    );
  }

  async redactProviderSandbox(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
    await client.query(
      `UPDATE provider_sandbox.customers
       SET email=$3, name=$4, external_reference=$5, updated_at=now()
       WHERE merchant_id=$1 AND payflow_customer_id=$2`,
      [merchantId, customerId, REDACTED.email, REDACTED.name, REDACTED.externalReference],
    );
  }

  async recordErasedCustomer(
    client: PoolClient,
    merchantId: string,
    customerId: string,
    requestId: string,
  ): Promise<void> {
    await client.query(
      `INSERT INTO customers.erased_customers(merchant_id,customer_id,request_id)
       VALUES($1,$2,$3) ON CONFLICT DO NOTHING`,
      [merchantId, customerId, requestId],
    );
  }

  async complete(client: PoolClient, requestId: string): Promise<void> {
    await client.query(
      `UPDATE customers.erasure_requests
       SET status='completed', completed_at=now(), updated_at=now(),
           locked_by=NULL, locked_at=NULL, lease_expires_at=NULL, last_error=NULL
       WHERE id=$1`,
      [requestId],
    );
  }

  async fail(request: ClaimedErasureRequest, error: unknown): Promise<void> {
    const message = STABLE_ERROR;
    const detail = error instanceof Error ? error.message.slice(0, 300) : String(error).slice(0, 300);
    await transaction(async (client) => {
      if (request.attempts >= request.max_attempts) {
        await client.query(
          `UPDATE customers.erasure_requests
           SET status='failed', locked_by=NULL, locked_at=NULL, lease_expires_at=NULL,
               last_error=$2, updated_at=now()
           WHERE id=$1`,
          [request.id, message],
        );
        await client.query(
          `INSERT INTO operations.dead_letters(source,source_id,event_type,payload,error)
           VALUES('erasure_request',$1,'customer.erasure',$2,$3)`,
