{"command":"create","path":"/workspace/source/apps/erasure-worker/src/processor.ts","file_text":"import { Redis } from 'ioredis';
import { config } from '../../../packages/config/src/index.js';
import { transaction } from '../../../packages/database/src/pool.js';
import { deleteMailpitMessagesForRecipient } from '../../../packages/notifications/src/mailpit.js';
import { CUSTOMER_INDEX, searchClient } from '../../../packages/search/src/client.js';
import { DOCUMENT_BUCKET, objectStore } from '../../../packages/storage/src/minio.js';
import {
  ErasureWorkerRepository,
  type ClaimedErasureRequest,
} from './repository.js';

const redis = new Redis(config().REDIS_URL);
const repository = new ErasureWorkerRepository();

async function deleteObjectQuietly(objectKey: string): Promise<void> {
  try {
    await objectStore.removeObject(DOCUMENT_BUCKET, objectKey);
  } catch {
    // Object may already be gone; manifests still get cleaned via DB redaction path.
  }
}

async function deleteSearchDocument(merchantId: string, customerId: string): Promise<void> {
  try {
    await searchClient.delete({
      index: CUSTOMER_INDEX,
      id: `${merchantId}:${customerId}`,
      refresh: true,
    });
  } catch (error) {
    const statusCode = (error as { meta?: { statusCode?: number } }).meta?.statusCode;
    if (statusCode !== 404) throw error;
  }
}

async function clearRedis(merchantId: string, customerId: string): Promise<void> {
  const cacheKey = `merchant:${merchantId}:customer:${customerId}`;
  await redis.del(cacheKey, `${cacheKey}:activity`);
}

async function runStep(
  request: ClaimedErasureRequest,
  done: Set<string>,
  step: string,
  work: () => Promise<void>,
): Promise<void> {
  if (done.has(step)) return;
  await work();
  await transaction(async (client) => {
    await repository.markStep(client, request.id, step);
  });
  done.add(step);
}

export async function processErasureRequest(request: ClaimedErasureRequest): Promise<void> {
  const done = await repository.completedSteps(request.id);
  const { merchant_id: merchantId, customer_id: customerId } = request;

  await runStep(request, done, 'capture_targets', async () => {
    const snapshot = await repository.loadCustomerPii(merchantId, customerId);
    await transaction(async (client) => {
      await repository.captureEmailTargets(client, request.id, merchantId, customerId, snapshot);
    });
  });

  const emailTargets = await repository.loadEmailTargets(request.id);

  await runStep(request, done, 'delete_objects', async () => {
    const keys = new Set<string>([
      ...(await repository.listDocumentKeys(merchantId, customerId)),
      ...(await repository.listImportKeys(merchantId, customerId)),
    ]);
    for (const key of keys) await deleteObjectQuietly(key);
  });

  await runStep(request, done, 'delete_search', async () => {
    await deleteSearchDocument(merchantId, customerId);
  });

  await runStep(request, done, 'delete_cache', async () => {
    await clearRedis(merchantId, customerId);
  });

  await runStep(request, done, 'delete_mail', async () => {
    for (const destination of emailTargets) {
      await deleteMailpitMessagesForRecipient(destination);
    }
  });

  await runStep(request, done, 'redact_database', async () => {
    await transaction(async (client) => {
      await repository.tombstoneCustomer(client, merchantId, customerId);
      await repository.redactProfileGraph(client, merchantId, customerId);
      await repository.redactFinancialRecords(client, merchantId, customerId);
      await repository.redactOperationalRecords(client, merchantId, customerId);
      await repository.redactProviderSandbox(client, merchantId, customerId);
      await repository.recordErasedCustomer(client, merchantId, customerId, request.id);
    });
  });

  // Re-clear external stores after DB redaction so late writers cannot leave PII behind.
  await runStep(request, done, 'reverify_external', async () => {
    await deleteSearchDocument(merchantId, customerId);
    await clearRedis(merchantId, customerId);
    for (const destination of emailTargets) {
      await deleteMailpitMessagesForRecipient(destination);
    }
  });

  await transaction(async (client) => {
    await repository.complete(client, request.id);
  });
}

export async function shutdownErasureProcessor(): Promise<void> {
  await redis.quit();
}
"}

{"command":"create","path":"/workspace/source/apps/erasure-worker/src/main.ts","file_text":"import { randomUUID } from 'node:crypto';
import { logger } from '../../../packages/observability/src/logger.js';
import { processErasureRequest, shutdownErasureProcessor } from './processor.js';
import { ErasureWorkerRepository } from './repository.js';

process.env.SERVICE_NAME = 'erasure-worker';
const workerId = `erasure-worker-${randomUUID()}`;
const repository = new ErasureWorkerRepository();
const controller = new AbortController();

async function run(signal: AbortSignal): Promise<void> {
  let lastLeaseRecovery = 0;
  while (!signal.aborted) {
    if (Date.now() - lastLeaseRecovery > 30_000) {
      await repository.recoverExpiredLeases();
      lastLeaseRecovery = Date.now();
    }
    const request = await repository.claim(workerId);
    if (!request) {
      await new Promise((resolve) => setTimeout(resolve, 250));
      continue;
    }
    try {
      await processErasureRequest(request);
      logger.info({ requestId: request.id, customerId: request.customer_id }, 'erasure completed');
    } catch (error) {
      logger.error({ error, requestId: request.id }, 'erasure request failed');
      await repository.fail(request, error);
    }
  }
}

void run(controller.signal);
logger.info({ workerId }, 'erasure worker started');
for (const signal of ['SIGTERM', 'SIGINT'] as const) {
  process.on(signal, () => {
    controller.abort();
    void shutdownErasureProcessor();
  });
}
"}

