import { isCustomerErased } from '../../../packages/privacy/src/erasure-guard.js';
import { redactedCustomerSnapshot } from '../../../packages/privacy/src/redaction.js';
import { recordReceiptManifest } from './repository.js';

process.env.SERVICE_NAME = 'document-worker';
type ReceiptJob = {
  merchantId: string; customerId: string; paymentId: string; amount: number;
  currency: string; customerSnapshot: Record<string, unknown>
};
const workerId = `document-worker-${randomUUID()}`;
const controller = new AbortController();

async function complete(job: ClaimedJob<ReceiptJob>): Promise<void> {
  const erased = await isCustomerErased(job.merchant_id, job.payload.customerId);
  const payload = erased
    ? { ...job.payload, customerSnapshot: redactedCustomerSnapshot(job.payload.customerId) }
    : job.payload;
  const stored = await storeReceipt(payload);
  await transaction(async (client) => {
    await recordReceiptManifest(client, {
