  }>> {
    const manifests = await pool.query<{
      object_key: string;
      document_type: string;
      payment_id: string | null;
      invoice_id: string | null;
      number: string | null;
    }>(
      `SELECT object_key, document_type,
              metadata->>'paymentId' AS payment_id,
              metadata->>'invoiceId' AS invoice_id,
              metadata->>'number' AS number
       FROM operations.document_manifests
       WHERE merchant_id=$1 AND (
         customer_id=$2 OR metadata->>'customerId'=$2::text
       )`,
      [merchantId, customerId],
    );
    const invoices = await pool.query<{
      object_key: string;
      invoice_id: string;
      number: string;
      total: string;
      currency: string;
    }>(
      `SELECT object_key, id::text AS invoice_id, number, total::text, currency
       FROM payments.invoices
       WHERE merchant_id=$1 AND customer_id=$2 AND object_key IS NOT NULL`,
      [merchantId, customerId],
    );
    const payments = await pool.query<{
      payment_id: string;
      amount: string;
      currency: string;
    }>(
      `SELECT id::text AS payment_id, amount::text, currency
       FROM payments.payment_intents
       WHERE merchant_id=$1 AND customer_id=$2`,
      [merchantId, customerId],
    );
    const paymentById = new Map(payments.rows.map((row) => [row.payment_id, row]));
    const byKey = new Map<string, {
      object_key: string;
      document_type: string;
      payment_id?: string | undefined;
      invoice_id?: string | undefined;
      number?: string | undefined;
      amount?: string | undefined;
      currency?: string | undefined;
    }>();
    for (const row of manifests.rows) {
      const payment = row.payment_id ? paymentById.get(row.payment_id) : undefined;
      byKey.set(row.object_key, {
        object_key: row.object_key,
        document_type: row.document_type,
        payment_id: row.payment_id ?? undefined,
        invoice_id: row.invoice_id ?? undefined,
        number: row.number ?? undefined,
        amount: payment?.amount,
        currency: payment?.currency,
      });
    }
    for (const row of invoices.rows) {
      const existing = byKey.get(row.object_key);
      byKey.set(row.object_key, {
        object_key: row.object_key,
        document_type: existing?.document_type ?? 'invoice',
        invoice_id: row.invoice_id,
        number: row.number,
        amount: row.total,
        currency: row.currency,
        payment_id: existing?.payment_id,
      });
    }
    return [...byKey.values()];
  }

  async scrubDocumentManifests(client: PoolClient, merchantId: string, customerId: string): Promise<void> {
